      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n10/12~15) 7세 유치원~ 여자 초등학생(1-6학년) 대면 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.07. 16:43\n조회 46\n구독\n10/12~15) 7세 유치원~ 남녀 초등학생(1-6학년) 대면 좌담회\n남자 여자 어린이 유치원(7세) ~ 초등학교 전학년 대상\n> 일시:10/12(월)-10/15(목)일 중 하루 / 3시,5시,7시\n> 소요시간 : 90분\n> 장소: 강남구청역 2번 출구 인근\n> 7세 유치원생, 남녀 초등학생 1-6학년\n> 부모 동반, 좌담회는 어린이만 참석\n> 사례비: 7만원\n* 유치원(7세), 초등학교 1~6학년 남자 / 여자아이\n* 활발하며 본인의 생각을 조리 있게 말할 수 있는 아이\n* 부모님과 동반하나 좌담회는 아이만 참석\n* 감염병(독감 등) 문제 없는 분\n※ 대중교통 이용\n< 신청시 기재 사항 >\n1. 부모님 - 이름 / 성별/ 나이 (주민번호 앞자리) / 거주구/ 연락처 / 자녀 성별 및 나이\n2. 참석 어린이 - 이름/ 성별/ 생년월 (예시) 2020년 05월 / 학교 학년\n3. 평소 즐기는 놀이 3가지\n4. 보호자 통화 가능 시간 (5분내외 소요)\n아이와 통화 가능한 시간 (2-3분 소요)\nhttps://forms.gle/Q8wEXWvCSxqNZzdn7\n10/12~15) 7세 유치원~ 남녀 초등학생(1-6학년) 대면 좌담회\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n0\n송파구 이웃끼리 공유하는 동네 꿀정보\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.07. 20:55 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n만 18세~30세 남녀) 온라인/모바일 게임 유저 패널\n좌담회알바좌담회카페\n26.09.07.\n댓글\n1\n10/12~15) 7세 유치원~ 여자 초등학생(1-6학년) 대면 좌담회\n좌담회알바좌담회카페\n26.09.07.\n댓글\n1\n10/12~15) 7세 유치원~ 남자 초등학생(1-6학년) 대면 좌담회\n좌담회알바좌담회카페\n26.09.07.\n댓글\n1\n수도권에 근무하고 있는 외국인 대상 ( 인터뷰 사레비 - 400,000원 세금 별도) 부패인식도 관련 심층인터뷰\n좌담회알바좌담회카페\n26.09.07.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
