      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n1시간 8만) 9/9~14)만18세 이상~58세,현재 서울/경기/인천 지역 거주자) 구글 플레이 스토어 및 모바일 게임 이용자 인터뷰\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.07. 17:26\n조회 80\n구독\n1시간 8만) 9/9~14)만18세 이상~58세,현재 서울/경기/인천 지역 거주자) 구글 플레이 스토어 및 모바일 게임 이용자 인터뷰\n신청하신분은 재신청 안하셔도 됩니다 ~\n이번에 저희는 구글플레이스토어 및 모바일 게임 이용자를 대상으로 온라인 인터뷰를 진행하고 있습니다.\n아래 내용에 해당되시면 신청해 주시면 고맙겠습니다.\n1. 조사대상\n- 만 18세 이상 ~ 58세, 현재 서울/경기/인천 지역 거주자\n- Android 스마트폰 이용자이면서 모바일 게임을 자주하는 사람\n- 최근 6개월 이내 모바일 게임 유료 결제 또는 인앱결제 경험이 있는 사람\n- 모바일 게임에 월 평균 10만원 이상 지출하는 사람\n- Google Play Points 회원(Google Play Points 등급 사진 제출 필요)\n- Google Play Store 외 게임 공식사이트 등에서 모바일 게임을 구매하거나 인앱결제한 경험이 있는 사람\n2. 조사방법과 사례\n- 방법 : 1:1 온라인 인터뷰 (약 60분 내외)\n- 일시 : 9/9(수) ~ 9/14(월) 중 진행 / 시간은 추후 안내드립니다\n- 사례 : 현금 8만원 계좌 입금\n3. 조사 참여신청\n- 신청양식\n이름/나이/성별/직업/거주지/현재 사용중인 스마트폰 기종/주로 플레이하는 모바일 게임/최근 6개월 내 모바일 게임 결제 경험/월 평균 모바일 게임 내 결제 금액/Google Play Points 등급\n- 신청 예시\n홍길동/34세/남자/회사원/서울시 동작구 흑석동/갤럭시Z폴드8 /리니지M/경험 있음/10만원/다이아몬드\n4. 대상 선정\n- 신청내용 확인 후 1. 문자로 대상 선정을 위한 온라인 링크 송부받아 링크에 응답, 2. 전화로 최종 확인\nhttps://forms.gle/DdNrKHzCwUnBCwWx5\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 핫한 진짜 동네 이야기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.07. 20:52 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n9월 진행예정) 만 19~59세 수도권 거주 성인남성 )구강청결제 사용자/비사용자 좌담회, 모바일 인터뷰\n좌담회알바좌담회카페\n26.09.07.\n댓글\n1\n1시간 8만) 9/9~14)만18세 이상~58세,현재 서울/경기/인천 지역 거주자) 구글 플레이 스토어 및 모바일 게임 이용자 인터뷰\n좌담회알바좌담회카페\n26.09.07.\n댓글\n1\n9/10~15) 만20-59세 남, 여) 간편식 관련 설문조사\n좌담회알바좌담회카페\n26.09.07.\n댓글\n1\n전국거주 만60세~69세 남녀) 9/21~10/2) 30분 8~10만) 온라인 설문조사)대형 VAN 차량 보유자\n좌담회알바좌담회카페\n26.09.07.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
